const activeKeys = new Set();
        let peakCount = 0;
        const countDisplay = document.getElementById('current-count');
        const peakDisplay = document.getElementById('peak-record');
        const peakBar = document.getElementById('peak-bar');
        const ratingDisplay = document.getElementById('hw-rating');
        const gridDisplay = document.getElementById('key-display-area');
        const hwDesc = document.getElementById('hw-desc');
        window.addEventListener('keydown', (e) => {
            e.preventDefault(); // Stop scrolling/shortcuts
            const keyStr = e.key === ' ' ? 'SPACE' : e.key.toUpperCase();
            activeKeys.add(keyStr);
            updateUI();
        });
        window.addEventListener('keyup', (e) => {
            const keyStr = e.key === ' ' ? 'SPACE' : e.key.toUpperCase();
            activeKeys.delete(keyStr);
            updateUI();
        });
        // Prevention for sticky keys if window loses focus
        window.onblur = () => {
            activeKeys.clear();
            updateUI();
        };
        function updateUI() {
            const currentSize = activeKeys.size;
            countDisplay.innerText = currentSize;
            // Handle Peak
            if (currentSize > peakCount) {
                peakCount = currentSize;
                peakDisplay.innerText = `${peakCount} Keys`;
                // Progress bar logic: assume 20 keys is "100%" of reasonable hand span
                const barPct = Math.min(100, (peakCount / 20) * 100);
                peakBar.style.width = barPct + '%';
                updateRating(peakCount);
            }
            // Update Visual Grid
            if (currentSize === 0) {
                gridDisplay.innerHTML = '<p class="text-slate-400 italic text-center font-medium">Place your palm across the keys to trigger the matrix sensors...</p>';
            } else {
                gridDisplay.innerHTML = '';
                activeKeys.forEach(key => {
                    const span = document.createElement('div');
                    span.className = 'active-key';
                    span.innerText = key;
                    gridDisplay.appendChild(span);
                });
            }
        }
        function updateRating(count) {
            let rating = "Office (2KRO)";
            let desc = "Standard membrane matrix detected. Not suitable for gaming.";
            let color = "text-slate-500";
            if (count >= 12) {
                rating = "Elite (NKRO+)";
                desc = "Professional tier. Mechanical or Optical matrix with unlimited rollover.";
                color = "text-blue-600";
            } else if (count >= 10) {
                rating = "Elite (NKRO)";
                desc = "Professional grade. No jamming detected in standard clusters.";
                color = "text-blue-600";
            } else if (count >= 6) {
                rating = "Gaming (6KRO)";
                desc = "USB HID standard limit. High-performance gaming optimized.";
                color = "text-emerald-500";
            } else if (count > 2) {
                rating = "Basic (Multi)";
                desc = "Improved matrix. Capable of simple simultaneous inputs.";
                color = "text-amber-500";
            }
            ratingDisplay.innerText = rating;
            ratingDisplay.className = `text-3xl font-black tracking-tighter ${color}`;
            hwDesc.innerText = desc;
        }
        function resetPeak() {
            peakCount = 0;
            peakDisplay.innerText = "0 Keys";
            peakBar.style.width = '0%';
            ratingDisplay.innerText = "STANDBY";
            ratingDisplay.className = "text-3xl font-black text-slate-400 tracking-tighter";
            hwDesc.innerText = "Awaiting linguistic input signal.";
        }
